draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = '#dfd7c7';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-70, 100, 140);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2, H/2+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2-30, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2+30, H/2+80);
  ctx.stroke();

  // Draw reading action
  ctx.beginPath();
  ctx.moveTo(W/2-20, H/2+60);
  ctx.lineTo(W/2-20+Math.sin(t)*10, H/2+60+Math.cos(t)*10);
  ctx.stroke();

  // Draw wisdom bubbles
  ctx.fillStyle = '#dfd7c7';
  ctx.beginPath();
  ctx.arc(W/2-60+Math.sin(t)*20, H/2+20+Math.cos(t)*20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2-40+Math.sin(t+1)*20, H/2+40+Math.cos(t+1)*20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
